use std::borrow::Borrow;
use std::fmt;

/// A point on the virtual clock, in whole seconds since start.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Default)]
pub struct Instant(u64);

impl Instant {
    pub fn after(self, seconds: u32) -> Self {
        Self(self.0 + u64::from(seconds))
    }

    pub fn advance(&mut self, seconds: u32) {
        *self = self.after(seconds);
    }

    pub fn as_secs(self) -> u64 {
        self.0
    }
}

/// A queue name. Lookups accept any string, so the type carries no syntax rule;
/// names given to `CreateQueue` are checked by the command parser.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct QueueName(String);

impl QueueName {
    pub fn new(name: String) -> Self {
        Self(name)
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl Borrow<str> for QueueName {
    fn borrow(&self) -> &str {
        &self.0
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct MessageId(u64);

impl fmt::Display for MessageId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "m-{}", self.0)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ReceiptNo(u64);

impl ReceiptNo {
    /// Parses the canonical text `r-<n>` with `n >= 1` and no sign, padding or spaces.
    pub fn parse(text: &str) -> Option<Self> {
        let digits = text.strip_prefix("r-")?;
        let canonical = !digits.starts_with('0') && digits.bytes().all(|b| b.is_ascii_digit());
        if !canonical {
            return None;
        }
        digits.parse().ok().map(Self)
    }
}

impl fmt::Display for ReceiptNo {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "r-{}", self.0)
    }
}

/// Position of a message in its queue's arrival order; never reused within a queue.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Slot(pub(crate) u64);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Sequence(pub(crate) u64);

impl Sequence {
    pub fn get(self) -> u64 {
        self.0
    }
}

fn is_token(text: &str) -> bool {
    (1..=128).contains(&text.len())
        && text
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct GroupId(String);

impl GroupId {
    pub fn parse(text: &str) -> Option<Self> {
        is_token(text).then(|| Self(text.to_owned()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct DedupId(String);

impl DedupId {
    pub fn parse(text: &str) -> Option<Self> {
        is_token(text).then(|| Self(text.to_owned()))
    }

    /// Content-based deduplication uses the body itself, of any length and content.
    pub fn from_body(body: &str) -> Self {
        Self(body.to_owned())
    }
}

/// Process-wide counters for message ids and receipt handles.
#[derive(Debug, Default)]
pub struct Ids {
    messages: u64,
    receipts: u64,
}

impl Ids {
    pub fn next_message(&mut self) -> MessageId {
        self.messages += 1;
        MessageId(self.messages)
    }

    pub fn next_receipt(&mut self) -> ReceiptNo {
        self.receipts += 1;
        ReceiptNo(self.receipts)
    }

    pub fn was_issued(&self, receipt: ReceiptNo) -> bool {
        (1..=self.receipts).contains(&receipt.0)
    }
}

